+                reflow_simd_store_stream<span>(half_params + i, param_4);
+            } else {
+                reflow_simd_store<span>(_params_fp32 + i, param_4);
+                reflow_simd_store<span>(_exp_avg + i, momentum_4);
+                reflow_simd_store<span>(_exp_avg_sq + i, variance_4);
+            }
+        }
+    }
+}
