+// Independent step counters for param vs. async-state updates.
+struct ReflowLionOptimizerPair {
+    std::shared_ptr<Reflow_Lion_Optimizer> param_opt;
+    std::shared_ptr<Reflow_Lion_Optimizer> state_opt;
+    // Bucket workers share the optimizer scalars; keep their updates serialized.
+    std::shared_ptr<std::mutex> param_opt_mutex;
+};
+static std::unordered_map<int, ReflowLionOptimizerPair> s_reflow_lion_optimizers;
+
+// Affinity-aware available-core count (falls back to omp_get_num_procs()).
+static unsigned int reflow_lion_get_available_cpu_count()
+{
+#ifdef __linux__
+    cpu_set_t cpuset;
+    CPU_ZERO(&cpuset);
+
+    if (sched_getaffinity(0, sizeof(cpu_set_t), &cpuset) == 0) {
+        unsigned int count = 0;
+        for (int i = 0; i < CPU_SETSIZE; i++) {
+            if (CPU_ISSET(i, &cpuset)) { count++; }
+        }
+        if (count > 0) { return count; }
+    }
+#endif
+    return omp_get_num_procs();
+}
+
+// Non-positive thread counts use all cores available to this worker.
+static unsigned int reflow_lion_resolve_omp_threads(int num_threads, unsigned int available)
+{
+    if (num_threads > 0) { return std::min(static_cast<unsigned int>(num_threads), available); }
+    return available;
+}
