+// Half/BFloat16 gradient FP16/BF16-store path (params only, skips state).
+template <typename ds_store_precision_t,
+          typename ds_grad_precision_t,
+          typename ds_state_precision_t>
+void Reflow_Lion_Optimizer::Step_8_FP16_HalfGrad(float* _params_fp32,
+                                                 ds_grad_precision_t* grads_half,
+                                                 ds_state_precision_t* _exp_avg,
+                                                 size_t _param_size,
+                                                 ds_store_precision_t* half_params,
+                                                 float combined_scale)
+{
+    size_t rounded_size = 0;
+#if defined(__AVX512__) or defined(__AVX256__)
+    Step_AVX_FP16_HalfGrad<8, ds_store_precision_t, ds_grad_precision_t, ds_state_precision_t>(
+        &rounded_size,
+        _params_fp32,
+        grads_half,
+        _exp_avg,
+        _param_size,
+        half_params,
+        combined_scale);
+    // Narrow the SIMD span before handling the remaining scalar tail.
+    if (_param_size > rounded_size) {
+        size_t tail_rounded_size = 0;
+        Step_AVX_FP16_HalfGrad<4, ds_store_precision_t, ds_grad_precision_t, ds_state_precision_t>(
+            &tail_rounded_size,
+            _params_fp32 + rounded_size,
+            grads_half + rounded_size,
+            _exp_avg + rounded_size,
+            _param_size - rounded_size,
+            half_params + rounded_size,
+            combined_scale);
+        rounded_size += tail_rounded_size;
+    }
+    if (_param_size > rounded_size) {
+        size_t tail_rounded_size = 0;
+        Step_AVX_FP16_HalfGrad<1, ds_store_precision_t, ds_grad_precision_t, ds_state_precision_t>(
+            &tail_rounded_size,
+            _params_fp32 + rounded_size,
+            grads_half + rounded_size,
+            _exp_avg + rounded_size,
+            _param_size - rounded_size,
+            half_params + rounded_size,
+            combined_scale);
+        rounded_size += tail_rounded_size;
+    }
+#endif
+    if (_param_size > rounded_size) {
+        float betta1_minus1 = 1 - _betta1;
+        float alpha = _alpha;
+        float after_decay = 1 - alpha * _weight_decay;
+        float unscale_factor = 1.0f / combined_scale;
+
+        for (size_t t = rounded_size; t < _param_size; t += TILE) {
+            size_t copy_size = TILE;
+            if ((t + TILE) > _param_size) copy_size = _param_size - t;
+            size_t offset = copy_size + t;
+            ReflowCPUAffinity affinity;
+#pragma omp parallel
+            {
+                affinity.apply();
+#pragma omp for schedule(static) nowait
+                for (size_t k = t; k < offset; k++) {
+                    float grad = static_cast<float>(grads_half[k]) * unscale_factor;
+                    float param = _params_fp32[k];
+                    float momentum = static_cast<float>(_exp_avg[k]);
+                    float tmp = momentum * _betta1;
+                    tmp = grad * betta1_minus1 + tmp;
+                    tmp = -std::copysignf(alpha, tmp);
+                    if (_weight_decay > 0) {
+                        param = param * after_decay + tmp;
+                    } else {
+                        param = param + tmp;
+                    }
+                    // Store param to FP16/BF16 buffer only; the FP32 master and state are skipped.
+                    half_params[k] = ds_store_precision_t(param);
+                }
+            }
+        }
+    }
+}
+
+// Half/BFloat16 gradient params (FP32 master) + state commit.
+template <typename ds_grad_precision_t, typename ds_state_precision_t>
+void Reflow_Lion_Optimizer::Step_8_State_HalfGrad(float* _params_fp32,
+                                                  ds_grad_precision_t* grads_half,
+                                                  ds_state_precision_t* _exp_avg,
+                                                  size_t _param_size,
+                                                  float combined_scale)
+{
+    size_t rounded_size = 0;
+#if defined(__AVX512__) or defined(__AVX256__)
+    Step_AVX_HalfGrad<8, ds_grad_precision_t, ds_state_precision_t>(
+        &rounded_size, _params_fp32, grads_half, _exp_avg, _param_size, combined_scale);
+    if (_param_size > rounded_size) {
+        size_t tail_rounded_size = 0;
+        Step_AVX_HalfGrad<4, ds_grad_precision_t, ds_state_precision_t>(&tail_rounded_size,
+                                                                        _params_fp32 + rounded_size,
+                                                                        grads_half + rounded_size,
+                                                                        _exp_avg + rounded_size,
+                                                                        _param_size - rounded_size,
+                                                                        combined_scale);
+        rounded_size += tail_rounded_size;
+    }
+    if (_param_size > rounded_size) {
+        size_t tail_rounded_size = 0;
+        Step_AVX_HalfGrad<1, ds_grad_precision_t, ds_state_precision_t>(&tail_rounded_size,
+                                                                        _params_fp32 + rounded_size,
+                                                                        grads_half + rounded_size,
+                                                                        _exp_avg + rounded_size,
+                                                                        _param_size - rounded_size,
+                                                                        combined_scale);
+        rounded_size += tail_rounded_size;
+    }
+#endif
+    if (_param_size > rounded_size) {
+        float betta1_minus1 = 1 - _betta1;
+        float betta2_minus1 = 1 - _betta2;
+        float alpha = _alpha;
+        float after_decay = 1 - alpha * _weight_decay;
+        float unscale_factor = 1.0f / combined_scale;
+
+        for (size_t t = rounded_size; t < _param_size; t += TILE) {
+            size_t copy_size = TILE;
+            if ((t + TILE) > _param_size) copy_size = _param_size - t;
+            size_t offset = copy_size + t;
+            ReflowCPUAffinity affinity;
+#pragma omp parallel
+            {
+                affinity.apply();
+#pragma omp for schedule(static) nowait
+                for (size_t k = t; k < offset; k++) {
+                    float grad = static_cast<float>(grads_half[k]) * unscale_factor;
+                    float param = _params_fp32[k];
+                    float momentum = static_cast<float>(_exp_avg[k]);
+                    float tmp = momentum * _betta1;
+                    tmp = grad * betta1_minus1 + tmp;
+                    tmp = -std::copysignf(alpha, tmp);
+                    if (_weight_decay > 0) {
+                        param = param * after_decay + tmp;
+                    } else {
+                        param = param + tmp;
+                    }
+                    momentum = momentum * _betta2;
+                    momentum = grad * betta2_minus1 + momentum;
+
+                    _params_fp32[k] = param;
+                    _exp_avg[k] = static_cast<ds_state_precision_t>(momentum);
+                }
+            }
+        }
+    }
+}
