+int reflow_create_lion_optimizer(int optimizer_id,
+                                 float alpha,
+                                 float betta1,
+                                 float betta2,
+                                 float weight_decay,
+                                 bool should_log,
+                                 int num_threads)
+{
+    // The Reflow half-grad kernels exist only for AVX2/AVX-512; fail here instead of at the first
+    // step.
+#if !(defined(__AVX512__) or defined(__AVX256__))
+    throw std::runtime_error("Reflow Lion requires a CPU build with AVX2 or AVX-512 support");
+#endif
+    auto parameter_opt =
+        std::make_shared<Reflow_Lion_Optimizer>(alpha, betta1, betta2, weight_decay);
+    auto state_opt = std::make_shared<Reflow_Lion_Optimizer>(alpha, betta1, betta2, weight_decay);
+    parameter_opt->set_num_threads(num_threads);
+    state_opt->set_num_threads(num_threads);
+    s_reflow_lion_optimizers[optimizer_id] =
+        ReflowLionOptimizerPair{parameter_opt, state_opt, std::make_shared<std::mutex>()};
+
+    if (should_log) {
+        std::string avx_type = "";
+#if defined(__AVX512__)
+        avx_type = "AVX512";
+#else
+        avx_type = "AVX2";
+#endif
+
+        printf("Reflow Lion Optimizer #%d is created with %s arithmetic capability.\n",
+               optimizer_id,
+               avx_type.c_str());
+        printf("Config: alpha=%f, betas=(%f, %f), weight_decay=%f\n",
+               alpha,
+               betta1,
+               betta2,
+               weight_decay);
+    }
+
+    return 0;
+}
+
+/* Half/BFloat16 gradient FP16-store path (params only, state skipped).
+ * params_fp32 stays FP32; the half_params buffer receives FP16/BF16.
+ */
+int reflow_ds_lion_step_params_halfgrad(int optimizer_id,
+                                        size_t step,
+                                        float lr,
+                                        float beta1,
+                                        float beta2,
+                                        float weight_decay,
+                                        torch::Tensor& params_fp32,
+                                        torch::Tensor& grads,
+                                        torch::Tensor& exp_avg,
+                                        torch::Tensor& half_params,
+                                        float combined_scale,
+                                        bool skip_increment_step)
+{
+    auto params_c = params_fp32.contiguous();
+    auto grads_c = grads.contiguous();
+    auto exp_avg_c = exp_avg.contiguous();
+    auto half_params_c = half_params.contiguous();
+
+    const size_t param_size = params_c.numel();
+    if (param_size == 0) { return 0; }
+
+    c10::ScalarType param_type = at::typeMetaToScalarType(params_c.options().dtype());
+    c10::ScalarType grad_type = at::typeMetaToScalarType(grads_c.options().dtype());
+    c10::ScalarType state_type = at::typeMetaToScalarType(exp_avg_c.options().dtype());
+    c10::ScalarType store_type = at::typeMetaToScalarType(half_params_c.options().dtype());
+
+    if (param_type != torch::kFloat32) {
+        throw std::runtime_error("reflow_ds_lion_step_params_halfgrad expects FP32 params tensor");
+    }
+    if (grad_type != torch::kFloat16 && grad_type != torch::kBFloat16) {
+        throw std::runtime_error(
+            "reflow_ds_lion_step_params_halfgrad expects FP16 or BF16 gradient tensor");
+    }
+    if (store_type != torch::kFloat16 && store_type != torch::kBFloat16) {
+        throw std::runtime_error(
+            "reflow_ds_lion_step_params_halfgrad expects FP16 or BF16 half_params tensor");
+    }
+
+    ReflowLionOptimizerPair& pair = s_reflow_lion_optimizers[optimizer_id];
+    std::shared_ptr<Reflow_Lion_Optimizer> opt = pair.param_opt;
+    Reflow_Lion_Optimizer worker_opt;
+    // Snapshot this range's scalars under the lock so another group cannot change them
+    // while its SIMD kernel runs. The disjoint parameter buffers still run in parallel.
+    // Keep the mutex alive even if its registry entry is replaced.
+    std::shared_ptr<std::mutex> opt_mutex = pair.param_opt_mutex;
+    {
+        std::lock_guard<std::mutex> opt_lock(*opt_mutex);
+        opt->IncrementStep(step, beta1, beta2);
+        opt->update_state(lr, weight_decay);
+        worker_opt = *opt;
+    }
+    // Honor the worker's CPU affinity to avoid oversubscribing its pinned cores.
+    unsigned int reflow_total_cpus = reflow_lion_get_available_cpu_count();
+    unsigned int reflow_max_omp_threads =
+        reflow_lion_resolve_omp_threads(worker_opt.get_num_threads(), reflow_total_cpus);
+    int reflow_original_omp_threads = omp_get_max_threads();
+    omp_set_num_threads(reflow_max_omp_threads);
+#if defined(__AVX512__) or defined(__AVX256__)
+    if (store_type == torch::kFloat16 && grad_type == torch::kFloat16 &&
+        state_type == torch::kFloat32) {
+        worker_opt.Step_8_FP16_HalfGrad<c10::Half, c10::Half, float>(
+            params_c.data_ptr<float>(),
+            grads_c.data_ptr<c10::Half>(),
+            exp_avg_c.data_ptr<float>(),
+            param_size,
+            half_params_c.data_ptr<c10::Half>(),
+            combined_scale);
+    } else if (store_type == torch::kFloat16 && grad_type == torch::kFloat16 &&
+               state_type == torch::kFloat16) {
+        worker_opt.Step_8_FP16_HalfGrad<c10::Half, c10::Half, c10::Half>(
+            params_c.data_ptr<float>(),
+            grads_c.data_ptr<c10::Half>(),
+            exp_avg_c.data_ptr<c10::Half>(),
+            param_size,
+            half_params_c.data_ptr<c10::Half>(),
+            combined_scale);
+    } else if (store_type == torch::kBFloat16 && grad_type == torch::kBFloat16 &&
+               state_type == torch::kFloat32) {
+        worker_opt.Step_8_FP16_HalfGrad<c10::BFloat16, c10::BFloat16, float>(
+            params_c.data_ptr<float>(),
+            grads_c.data_ptr<c10::BFloat16>(),
+            exp_avg_c.data_ptr<float>(),
+            param_size,
+            half_params_c.data_ptr<c10::BFloat16>(),
+            combined_scale);
+    } else if (store_type == torch::kBFloat16 && grad_type == torch::kBFloat16 &&
+               state_type == torch::kBFloat16) {
+        worker_opt.Step_8_FP16_HalfGrad<c10::BFloat16, c10::BFloat16, c10::BFloat16>(
+            params_c.data_ptr<float>(),
+            grads_c.data_ptr<c10::BFloat16>(),
+            exp_avg_c.data_ptr<c10::BFloat16>(),
+            param_size,
+            half_params_c.data_ptr<c10::BFloat16>(),
+            combined_scale);
+    } else
+#endif
+    {
+        omp_set_num_threads(reflow_original_omp_threads);
+        throw std::runtime_error(
+            "reflow_ds_lion_step_params_halfgrad: unsupported combination of store/grad/state "
+            "dtypes");
+    }
+    omp_set_num_threads(reflow_original_omp_threads);
+    return 0;
+}
+
+// Half/BFloat16 gradient params (FP32 master) + state commit.
+int reflow_ds_lion_state_step_halfgrad(int optimizer_id,
+                                       size_t step,
+                                       float lr,
+                                       float beta1,
+                                       float beta2,
+                                       float weight_decay,
+                                       torch::Tensor& params_fp32,
+                                       torch::Tensor& grads,
+                                       torch::Tensor& exp_avg,
+                                       float combined_scale,
+                                       bool skip_increment_step)
+{
+    unsigned int total_cpus = reflow_lion_get_available_cpu_count();
+    int configured_num_threads =
+        s_reflow_lion_optimizers[optimizer_id].state_opt->get_num_threads();
+    unsigned int max_omp_threads =
+        reflow_lion_resolve_omp_threads(configured_num_threads, total_cpus);
+    int original_num_threads = omp_get_max_threads();
+    omp_set_num_threads(max_omp_threads);
+
+    auto params_c = params_fp32.contiguous();
+    auto grads_c = grads.contiguous();
+    auto exp_avg_c = exp_avg.contiguous();
+
+    const size_t param_size = params_c.numel();
+    if (param_size == 0) {
+        omp_set_num_threads(original_num_threads);
+        return 0;
+    }
+
+    c10::ScalarType param_type = at::typeMetaToScalarType(params_c.options().dtype());
+    c10::ScalarType grad_type = at::typeMetaToScalarType(grads_c.options().dtype());
+    c10::ScalarType state_type = at::typeMetaToScalarType(exp_avg_c.options().dtype());
+
+    if (param_type != torch::kFloat32) {
+        omp_set_num_threads(original_num_threads);
+        throw std::runtime_error("reflow_ds_lion_state_step_halfgrad expects FP32 params tensor");
+    }
+    if (grad_type != torch::kFloat16 && grad_type != torch::kBFloat16) {
+        omp_set_num_threads(original_num_threads);
+        throw std::runtime_error(
+            "reflow_ds_lion_state_step_halfgrad expects FP16 or BF16 gradient tensor");
+    }
+
+    std::shared_ptr<Reflow_Lion_Optimizer> opt = s_reflow_lion_optimizers[optimizer_id].state_opt;
+    if (!skip_increment_step) {
+        opt->IncrementStep(step, beta1, beta2);
+        opt->update_state(lr, weight_decay);
+    }
+    // state_opt keeps its default skip-store flags (false, false) -> commits master + momentum.
+#if defined(__AVX512__) or defined(__AVX256__)
+    if (grad_type == torch::kFloat16 && state_type == torch::kFloat32) {
+        opt->Step_8_State_HalfGrad<c10::Half, float>(params_c.data_ptr<float>(),
+                                                     grads_c.data_ptr<c10::Half>(),
+                                                     exp_avg_c.data_ptr<float>(),
+                                                     param_size,
+                                                     combined_scale);
+    } else if (grad_type == torch::kFloat16 && state_type == torch::kFloat16) {
+        opt->Step_8_State_HalfGrad<c10::Half, c10::Half>(params_c.data_ptr<float>(),
+                                                         grads_c.data_ptr<c10::Half>(),
+                                                         exp_avg_c.data_ptr<c10::Half>(),
+                                                         param_size,
+                                                         combined_scale);
+    } else if (grad_type == torch::kBFloat16 && state_type == torch::kFloat32) {
+        opt->Step_8_State_HalfGrad<c10::BFloat16, float>(params_c.data_ptr<float>(),
+                                                         grads_c.data_ptr<c10::BFloat16>(),
+                                                         exp_avg_c.data_ptr<float>(),
+                                                         param_size,
+                                                         combined_scale);
+    } else if (grad_type == torch::kBFloat16 && state_type == torch::kBFloat16) {
+        opt->Step_8_State_HalfGrad<c10::BFloat16, c10::BFloat16>(
+            params_c.data_ptr<float>(),
+            grads_c.data_ptr<c10::BFloat16>(),
+            exp_avg_c.data_ptr<c10::BFloat16>(),
+            param_size,
+            combined_scale);
+    } else
+#endif
+    {
+        omp_set_num_threads(original_num_threads);
+        throw std::runtime_error(
+            "reflow_ds_lion_state_step_halfgrad: unsupported combination of grad/state dtypes");
+    }
+    omp_set_num_threads(original_num_threads);
+    return 0;
+}
+
+int reflow_destroy_lion_optimizer(int optimizer_id)
+{
+    s_reflow_lion_optimizers.erase(optimizer_id);
+
+    return 0;
+}
